// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    Owner ownerHelper;

    function setUp() public {
        ownerHelper = new Owner();
        c = ownerHelper.c();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount >= 2 && amount <= 1e30);
        vm.deal(address(this), amount);
        (bool okDep, ) = address(c).call{value: amount}("");
        assertTrue(okDep);
        assertTrue(address(c).balance == amount);

        // owner drives c through withdrawAll; the owner rejects payments of 1 wei,
        // so only a payout of the FULL balance is accepted.
        bool ok;
        try ownerHelper.callWithdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && address(c).balance == 0);
    }
}

contract Owner {
    SimpleWallet public c;

    constructor() {
        c = new SimpleWallet();
    }

    function callWithdrawAll() external {
        c.withdrawAll();
    }

    receive() external payable {
        require(msg.value > 1);
    }
}
